  @Test
  public void testDynamicPropertiesEqualsAndHashCode_whenOtherIsEqual_thenReturnEqual() {
    // Arrange
    Protocol.DynamicProperties defaultInstance = Protocol.DynamicProperties.getDefaultInstance();
    Protocol.DynamicProperties defaultInstance2 = Protocol.DynamicProperties.getDefaultInstance();

    // Act and Assert
    assertEquals(defaultInstance, defaultInstance2);
    int expectedHashCodeResult = defaultInstance.hashCode();
    assertEquals(expectedHashCodeResult, defaultInstance2.hashCode());
  }

