  /**
   * Method under test: {@link Protocol.ReasonCode#forNumber(int)}
   */
  @Test
  public void testReasonCodeForNumber() {
    // Arrange, Act and Assert
    assertNull(Protocol.ReasonCode.forNumber(Protocol.Account.DELEGATED_FROZEN_BALANCE_FOR_BANDWIDTH_FIELD_NUMBER));
    assertEquals(Protocol.ReasonCode.REQUESTED, Protocol.ReasonCode.forNumber(0));
    assertEquals(Protocol.ReasonCode.BAD_PROTOCOL, Protocol.ReasonCode.forNumber(2));
    assertEquals(Protocol.ReasonCode.TOO_MANY_PEERS, Protocol.ReasonCode.forNumber(4));
    assertEquals(Protocol.ReasonCode.DUPLICATE_PEER, Protocol.ReasonCode.forNumber(5));
    assertEquals(Protocol.ReasonCode.INCOMPATIBLE_PROTOCOL, Protocol.ReasonCode.forNumber(6));
    assertEquals(Protocol.ReasonCode.RANDOM_ELIMINATION, Protocol.ReasonCode.forNumber(7));
    assertEquals(Protocol.ReasonCode.PEER_QUITING, Protocol.ReasonCode.forNumber(8));
    assertEquals(Protocol.ReasonCode.UNEXPECTED_IDENTITY,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.UNEXPECTED_IDENTITY_VALUE));
    assertEquals(Protocol.ReasonCode.LOCAL_IDENTITY,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.LOCAL_IDENTITY_VALUE));
    assertEquals(Protocol.ReasonCode.PING_TIMEOUT,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.PING_TIMEOUT_VALUE));
    assertEquals(Protocol.ReasonCode.USER_REASON, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.USER_REASON_VALUE));
    assertEquals(Protocol.ReasonCode.RESET, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.RESET_VALUE));
    assertEquals(Protocol.ReasonCode.SYNC_FAIL, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.SYNC_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.FETCH_FAIL, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.FETCH_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.BAD_TX, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.BAD_TX_VALUE));
    assertEquals(Protocol.ReasonCode.BAD_BLOCK, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.BAD_BLOCK_VALUE));
    assertEquals(Protocol.ReasonCode.FORKED, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.FORKED_VALUE));
    assertEquals(Protocol.ReasonCode.UNLINKABLE, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.UNLINKABLE_VALUE));
    assertEquals(Protocol.ReasonCode.INCOMPATIBLE_VERSION,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.INCOMPATIBLE_VERSION_VALUE));
    assertEquals(Protocol.ReasonCode.INCOMPATIBLE_CHAIN,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.INCOMPATIBLE_CHAIN_VALUE));
    assertEquals(Protocol.ReasonCode.TIME_OUT, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.TIME_OUT_VALUE));
    assertEquals(Protocol.ReasonCode.CONNECT_FAIL,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.CONNECT_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.TOO_MANY_PEERS_WITH_SAME_IP,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.TOO_MANY_PEERS_WITH_SAME_IP_VALUE));
    assertEquals(Protocol.ReasonCode.LIGHT_NODE_SYNC_FAIL,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.LIGHT_NODE_SYNC_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.BELOW_THAN_ME,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.BELOW_THAN_ME_VALUE));
    assertEquals(Protocol.ReasonCode.NOT_WITNESS, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.NOT_WITNESS_VALUE));
    assertEquals(Protocol.ReasonCode.NO_SUCH_MESSAGE,
        Protocol.ReasonCode.forNumber(Protocol.ReasonCode.NO_SUCH_MESSAGE_VALUE));
    assertEquals(Protocol.ReasonCode.UNKNOWN, Protocol.ReasonCode.forNumber(Protocol.ReasonCode.UNKNOWN_VALUE));
  }

