  @Test
  public void testReasonCodeValueOf() {
    // Arrange, Act and Assert
    assertNull(Protocol.ReasonCode.valueOf(Protocol.Account.DELEGATED_FROZEN_BALANCE_FOR_BANDWIDTH_FIELD_NUMBER));
    assertEquals(Protocol.ReasonCode.REQUESTED, Protocol.ReasonCode.valueOf(0));
    assertEquals(Protocol.ReasonCode.BAD_PROTOCOL, Protocol.ReasonCode.valueOf(2));
    assertEquals(Protocol.ReasonCode.TOO_MANY_PEERS, Protocol.ReasonCode.valueOf(4));
    assertEquals(Protocol.ReasonCode.DUPLICATE_PEER, Protocol.ReasonCode.valueOf(5));
    assertEquals(Protocol.ReasonCode.INCOMPATIBLE_PROTOCOL, Protocol.ReasonCode.valueOf(6));
    assertEquals(Protocol.ReasonCode.RANDOM_ELIMINATION, Protocol.ReasonCode.valueOf(7));
    assertEquals(Protocol.ReasonCode.PEER_QUITING, Protocol.ReasonCode.valueOf(8));
    assertEquals(Protocol.ReasonCode.UNEXPECTED_IDENTITY,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.UNEXPECTED_IDENTITY_VALUE));
    assertEquals(Protocol.ReasonCode.LOCAL_IDENTITY,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.LOCAL_IDENTITY_VALUE));
    assertEquals(Protocol.ReasonCode.PING_TIMEOUT, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.PING_TIMEOUT_VALUE));
    assertEquals(Protocol.ReasonCode.USER_REASON, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.USER_REASON_VALUE));
    assertEquals(Protocol.ReasonCode.RESET, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.RESET_VALUE));
    assertEquals(Protocol.ReasonCode.SYNC_FAIL, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.SYNC_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.FETCH_FAIL, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.FETCH_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.BAD_TX, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.BAD_TX_VALUE));
    assertEquals(Protocol.ReasonCode.BAD_BLOCK, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.BAD_BLOCK_VALUE));
    assertEquals(Protocol.ReasonCode.FORKED, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.FORKED_VALUE));
    assertEquals(Protocol.ReasonCode.UNLINKABLE, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.UNLINKABLE_VALUE));
    assertEquals(Protocol.ReasonCode.INCOMPATIBLE_VERSION,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.INCOMPATIBLE_VERSION_VALUE));
    assertEquals(Protocol.ReasonCode.INCOMPATIBLE_CHAIN,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.INCOMPATIBLE_CHAIN_VALUE));
    assertEquals(Protocol.ReasonCode.TIME_OUT, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.TIME_OUT_VALUE));
    assertEquals(Protocol.ReasonCode.CONNECT_FAIL, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.CONNECT_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.TOO_MANY_PEERS_WITH_SAME_IP,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.TOO_MANY_PEERS_WITH_SAME_IP_VALUE));
    assertEquals(Protocol.ReasonCode.LIGHT_NODE_SYNC_FAIL,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.LIGHT_NODE_SYNC_FAIL_VALUE));
    assertEquals(Protocol.ReasonCode.BELOW_THAN_ME,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.BELOW_THAN_ME_VALUE));
    assertEquals(Protocol.ReasonCode.NOT_WITNESS, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.NOT_WITNESS_VALUE));
    assertEquals(Protocol.ReasonCode.NO_SUCH_MESSAGE,
        Protocol.ReasonCode.valueOf(Protocol.ReasonCode.NO_SUCH_MESSAGE_VALUE));
    assertEquals(Protocol.ReasonCode.UNKNOWN, Protocol.ReasonCode.valueOf(Protocol.ReasonCode.UNKNOWN_VALUE));
  }

