  /**
   * Method under test: {@link Protocol.ResourceReceipt#parseFrom(InputStream)}
   */
  @Test
  public void testResourceReceiptParseFrom6() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class, () -> Protocol.ResourceReceipt.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

  /**
   * Method under test: {@link Protocol.ResourceReceipt#parseFrom(InputStream)}
   */
  @Test
  public void testResourceReceiptParseFrom7() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class, () -> Protocol.ResourceReceipt.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

