  /**
   * Method under test:
   * {@link Protocol.TransactionInfo#internalGetMapFieldReflection(int)}
   */
  @Test
  public void testTransactionInfoInternalGetMapFieldReflection2() {
    // Arrange and Act
    MapFieldReflectionAccessor actualInternalGetMapFieldReflectionResult = Protocol.TransactionInfo.getDefaultInstance()
        .internalGetMapFieldReflection(Protocol.TransactionInfo.CANCEL_UNFREEZEV2_AMOUNT_FIELD_NUMBER);

    // Assert
    assertTrue(actualInternalGetMapFieldReflectionResult instanceof MapField);
    assertTrue(((MapField<Object, Object>) actualInternalGetMapFieldReflectionResult).isMutable());
    assertTrue(((MapField<Object, Object>) actualInternalGetMapFieldReflectionResult).getMap().isEmpty());
    assertTrue(((MapField<Object, Object>) actualInternalGetMapFieldReflectionResult).getMutableMap().isEmpty());
  }

