  /**
   * Method under test:
   * {@link Protocol.Transaction.Result.contractResult#valueOf(int)}
   */
  @Test
  public void testTransaction_Result_contractResultValueOf() {
    // Arrange, Act and Assert
    assertNull(Protocol.Transaction.Result.contractResult
        .valueOf(Protocol.Account.DELEGATED_FROZEN_BALANCE_FOR_BANDWIDTH_FIELD_NUMBER));
    assertEquals(Protocol.Transaction.Result.contractResult.DEFAULT,
        Protocol.Transaction.Result.contractResult.valueOf(0));
    assertEquals(Protocol.Transaction.Result.contractResult.SUCCESS,
        Protocol.Transaction.Result.contractResult.valueOf(1));
    assertEquals(Protocol.Transaction.Result.contractResult.REVERT,
        Protocol.Transaction.Result.contractResult.valueOf(2));
    assertEquals(Protocol.Transaction.Result.contractResult.BAD_JUMP_DESTINATION,
        Protocol.Transaction.Result.contractResult.valueOf(3));
    assertEquals(Protocol.Transaction.Result.contractResult.OUT_OF_MEMORY,
        Protocol.Transaction.Result.contractResult.valueOf(4));
    assertEquals(Protocol.Transaction.Result.contractResult.PRECOMPILED_CONTRACT,
        Protocol.Transaction.Result.contractResult.valueOf(5));
    assertEquals(Protocol.Transaction.Result.contractResult.STACK_TOO_SMALL,
        Protocol.Transaction.Result.contractResult.valueOf(6));
    assertEquals(Protocol.Transaction.Result.contractResult.STACK_TOO_LARGE,
        Protocol.Transaction.Result.contractResult.valueOf(7));
    assertEquals(Protocol.Transaction.Result.contractResult.ILLEGAL_OPERATION,
        Protocol.Transaction.Result.contractResult.valueOf(8));
    assertEquals(Protocol.Transaction.Result.contractResult.STACK_OVERFLOW, Protocol.Transaction.Result.contractResult
        .valueOf(Protocol.Transaction.Result.contractResult.STACK_OVERFLOW_VALUE));
    assertEquals(Protocol.Transaction.Result.contractResult.OUT_OF_ENERGY, Protocol.Transaction.Result.contractResult
        .valueOf(Protocol.Transaction.Result.contractResult.OUT_OF_ENERGY_VALUE));
    assertEquals(Protocol.Transaction.Result.contractResult.OUT_OF_TIME, Protocol.Transaction.Result.contractResult
        .valueOf(Protocol.Transaction.Result.contractResult.OUT_OF_TIME_VALUE));
    assertEquals(Protocol.Transaction.Result.contractResult.JVM_STACK_OVER_FLOW,
        Protocol.Transaction.Result.contractResult
            .valueOf(Protocol.Transaction.Result.contractResult.JVM_STACK_OVER_FLOW_VALUE));
    assertEquals(Protocol.Transaction.Result.contractResult.UNKNOWN,
        Protocol.Transaction.Result.contractResult.valueOf(Protocol.Transaction.Result.contractResult.UNKNOWN_VALUE));
    assertEquals(Protocol.Transaction.Result.contractResult.TRANSFER_FAILED, Protocol.Transaction.Result.contractResult
        .valueOf(Protocol.Transaction.Result.contractResult.TRANSFER_FAILED_VALUE));
    assertEquals(Protocol.Transaction.Result.contractResult.INVALID_CODE, Protocol.Transaction.Result.contractResult
        .valueOf(Protocol.Transaction.Result.contractResult.INVALID_CODE_VALUE));
  }

