  /**
   * Method under test: {@link Protocol.Witness#getUrlBytes()}
   */
  @Test
  public void testWitnessGetUrlBytes() {
    // Arrange
    Protocol.Witness defaultInstance = Protocol.Witness.getDefaultInstance();

    // Act
    ByteString actualUrlBytes = defaultInstance.getUrlBytes();

    // Assert
    ByteString byteString = actualUrlBytes.EMPTY;
    assertEquals(byteString, actualUrlBytes);
    List<Descriptors.FieldDescriptor> fields = defaultInstance.getDescriptorForType().getFields();
    assertEquals(Protocol.Witness.ISJOBS_FIELD_NUMBER, fields.size());
    assertSame(byteString, fields.get(0).getDefaultValue());
    assertSame(byteString, defaultInstance.getAddress());
    assertSame(byteString, defaultInstance.getPubKey());
  }

